/**
 * Public profile identifiers.
 *
 * A public identifier is the only thing encoded in a QR code or NFC tag. It is
 * an opaque, high-entropy, non-sequential token with no relationship to any
 * database key, name, email or phone number.
 *
 * Format: 26 symbols of Crockford base32 (130 bits of entropy).
 * - Case-insensitive and free of the ambiguous letters I, L, O and U, so it can
 *   be printed on a card and typed by hand by someone helping in an emergency.
 * - Canonical form is upper case without separators.
 *
 * Production identifiers are generated by the database (see ADR-0005). The
 * generator here exists for backend functions and tests, and uses only a
 * cryptographically secure random source.
 */

export const PUBLIC_ID_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
export const PUBLIC_ID_LENGTH = 26;
export const PUBLIC_ID_ENTROPY_BITS = PUBLIC_ID_LENGTH * 5;

declare const publicIdBrand: unique symbol;
/** A canonical, validated public identifier. */
export type PublicId = string & { readonly [publicIdBrand]: true };

const CANONICAL_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

/** Characters people commonly confuse, mapped per the Crockford specification. */
const CONFUSABLES: Readonly<Record<string, string>> = { O: '0', I: '1', L: '1' };

/**
 * Normalises user- or URL-supplied input into a canonical public identifier.
 * Accepts lower case, hyphens and spaces used for readability, and the
 * Crockford confusable letters. Returns `null` for anything else.
 */
export function parsePublicId(input: string): PublicId | null {
  if (input.length > PUBLIC_ID_LENGTH * 2) return null;
  const canonical = input
    .toUpperCase()
    .replace(/[\s-]/g, '')
    .replace(/[OIL]/g, (ch) => CONFUSABLES[ch] ?? ch);
  return CANONICAL_PATTERN.test(canonical) ? (canonical as PublicId) : null;
}

export function isPublicId(input: string): input is PublicId {
  return CANONICAL_PATTERN.test(input);
}

/** Splits an identifier into groups for printing, e.g. `ABCD-EFGH-…`. */
export function formatPublicIdForPrint(id: PublicId, groupSize = 4): string {
  const groups: string[] = [];
  for (let i = 0; i < id.length; i += groupSize) groups.push(id.slice(i, i + groupSize));
  return groups.join('-');
}

export type RandomSource = (bytes: Uint8Array<ArrayBuffer>) => Uint8Array;

const secureRandom: RandomSource = (bytes) => globalThis.crypto.getRandomValues(bytes);

/** Generates a new identifier from a cryptographically secure random source. */
export function generatePublicId(random: RandomSource = secureRandom): PublicId {
  const bytes = random(new Uint8Array(Math.ceil(PUBLIC_ID_ENTROPY_BITS / 8)));
  let out = '';
  let buffer = 0;
  let bits = 0;
  for (const byte of bytes) {
    buffer = (buffer << 8) | byte;
    bits += 8;
    while (bits >= 5 && out.length < PUBLIC_ID_LENGTH) {
      bits -= 5;
      out += PUBLIC_ID_ALPHABET[(buffer >> bits) & 31];
    }
    buffer &= (1 << bits) - 1;
  }
  return out as PublicId;
}
